    result = []
    space_count = 0

    for char in text:
        if char == " ":
            space_count += 1
        else:
            if space_count > 2:
                result.extend(['-'] * space_count)
            else:
                result.extend([' '] * space_count)
            result.append(char)
            space_count = 0

    # Handle trailing spaces
    if space_count > 2:
        result.extend(['-'] * space_count)
    else:
        result.extend([' '] * space_count)

    return ''.join(result)

